try {
  let content = $('OpenAI Intent Extractor').item.json.message.content;
  if (content.startsWith('```json')) {
    content = content.substring(7, content.length - 3);
  }
  return [{
    json: {
      status: "PREVIEW_REQUIRED",
      message: "Here are the suggested tasks. Please confirm.",
      suggested_tasks: JSON.parse(content)
    }
  }];
} catch (e) {
  return [{ json: { status: "ERROR", message: "Failed to parse tasks", suggested_tasks: [] } }];
}
